code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen=set(); objs=[]
    for r in range(h):
        for c in range(w):
            col=grid[r][c]
            if col==0 or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==col:
                        seen.add((ny,nx)); q.append((ny,nx))
            minr=min(y for y,x in cells); maxr=max(y for y,x in cells)
            minc=min(x for y,x in cells); maxc=max(x for y,x in cells)
            mask={(y-minr,x-minc) for y,x in cells}
            # An enclosed background cell marks a hollow frame.
            bh=maxr-minr+1; bw=maxc-minc+1
            bg={(y,x) for y in range(bh) for x in range(bw) if (y,x) not in mask}
            outside=set(); stack=[]
            for y,x in bg:
                if y in (0,bh-1) or x in (0,bw-1): outside.add((y,x)); stack.append((y,x))
            while stack:
                y,x=stack.pop()
                for p2 in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if p2 in bg and p2 not in outside: outside.add(p2); stack.append(p2)
            hollow=bool(bg-outside)
            objs.append(dict(col=col, cells=mask, r=minr,c=minc,h=bh,w=bw,hollow=hollow))
    placed=[]
    def free(obj, y):
        for other, oy in placed:
            if any((y+dy,x+obj['c'])==(oy+dy2,x2+other['c']) for dy,x in obj['cells'] for dy2,x2 in other['cells']):
                return False
        return True
    # Hollow objects settle upward; non-hollow objects settle downward.
    for obj in sorted((o for o in objs if o['hollow']), key=lambda o:o['r']):
        y=0
        while y+obj['h']<=h and not free(obj,y): y+=1
        placed.append((obj,y))
    for obj in sorted((o for o in objs if not o['hollow']), key=lambda o:o['r'], reverse=True):
        y=h-obj['h']
        while y>=0 and not free(obj,y): y-=1
        placed.append((obj,y))
    out=[[0]*w for _ in range(h)]
    for obj,y in placed:
        for dy,dx in obj['cells']: out[y+dy][obj['c']+dx]=obj['col']
    return out
'''
